-- Four Year 3 instructional corrections, Week 9 English and Mathematics.

UPDATE lessons SET title='Information Reports: Make Visuals Work',data=json_patch(data,'{"seed_key":"s2-eng-y3-w09-l2","title":"Information Reports: Make Visuals Work","stage":"Stage 2","learning_area":"English","year_level":3,"week":9,"lesson_number":2,"duration_minutes":60,"child_mission":"Learn information reports: make visuals work through explicit examples, guided work and an independent task.","learning_intention":"We are learning to apply information reports: make visuals work accurately and explain our choices.","success_criteria":["I can explain the central idea.","I can work through four taught concepts.","I can practise using supportive feedback.","I can complete an original independent task.","I can check my work and explain one improvement."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"The four learning concepts","cards":[{"front":"Match the visual to the information","back":"Choose a diagram for parts or positions, a bar chart for comparing counts, and a caption to tell readers what the picture represents."},{"front":"Give the visual accurate labels","back":"A chart needs a title, category labels, a numerical scale and sensible units. The heights must match the numbers."},{"front":"Use a caption that stays within the evidence","back":"A caption explains what the reader sees and can connect it to the report. Avoid extending a one-day survey to every day."},{"front":"Write the report around the visual","back":"A visual supports sentences but does not replace an introduction, explanatory paragraph or careful conclusion."}]}],"printable_resource":{"title":"Information Reports: Make Visuals Work","instructions":"Read the source and teacher model, attempt guided practice and then your independent challenge.","passage":"A class report says: ''Our school garden has four raised beds. Last Tuesday, students saw nine bees, seven butterflies and two dragonflies.''","prompts":["What does the source show?","Which method or text feature helps?","Complete your own response.","Explain how you checked."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Match the visual to the information","explain":"**Learn:** Choose a diagram for parts or positions, a bar chart for comparing counts, and a caption to tell readers what the picture represents.\n\n**Original source:** A class report says: ''Our school garden has four raised beds. Last Tuesday, students saw nine bees, seven butterflies and two dragonflies.''\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** To compare bee, butterfly and dragonfly sightings, I choose a bar chart, not a drawing of one large bee.\n\n**GUIDED TRY:** Guided: A recycling club records paper 12, cans 5 and bottles 8. Select a bar chart, label a 0–12 count scale, choose a caption and write one accurate comparison. Feedback: Paper has the highest recorded count, but the data do not establish which material is most recycled across Australia.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"Choose a diagram for parts or positions, a bar chart for comparing counts, and a caption to tell readers what the picture represents.","check":{"question":"Which visual best compares four counts?","options":["Bar chart","Single animal portrait","Map of Australia","Clock"],"correct_index":0,"explanation":"Bar chart. To compare bee, butterfly and dragonfly sightings, I choose a bar chart, not a drawing of one large bee."},"visual_before":[{"episode":{"title":"Investigating Information Reports: Make Visuals Work","transcript":"Pip: I have four insect counts. Should I draw one enormous butterfly?\nJuno: A bar chart makes the counts easier to compare. Label each bar.\nPip: My caption will say these are observations from one class survey.\nJuno: Exactly. Pause and explain why that caption should not make a claim about every garden.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I have four insect counts. Should I draw one enormous butterfly?"},{"who":"juno","text":"A bar chart makes the counts easier to compare. Label each bar."},{"who":"pip","text":"My caption will say these are observations from one class survey."},{"who":"juno","text":"Exactly. Pause and explain why that caption should not make a claim about every garden.","pause_after":true}]}]}}]},{"icon":"📖","title":"Give the visual accurate labels","explain":"**Learn:** A chart needs a title, category labels, a numerical scale and sensible units. The heights must match the numbers.\n\n**Original source:** A class report says: ''Our school garden has four raised beds. Last Tuesday, students saw nine bees, seven butterflies and two dragonflies.''\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** Title: Insects Seen on Tuesday. Bars: bees 9, butterflies 7, dragonflies 2. The scale counts sightings from zero.\n\n**GUIDED TRY:** Guided: A recycling club records paper 12, cans 5 and bottles 8. Select a bar chart, label a 0–12 count scale, choose a caption and write one accurate comparison. Feedback: Paper has the highest recorded count, but the data do not establish which material is most recycled across Australia.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"A chart needs a title, category labels, a numerical scale and sensible units. The heights must match the numbers.","check":{"question":"What must the vertical chart scale show?","options":["Counts","Only colours","The author''s favourite insect","No units"],"correct_index":0,"explanation":"Counts. Title: Insects Seen on Tuesday. Bars: bees 9, butterflies 7, dragonflies 2. The scale counts sightings from zero."}},{"icon":"✏️","title":"Use a caption that stays within the evidence","explain":"**Learn:** A caption explains what the reader sees and can connect it to the report. Avoid extending a one-day survey to every day.\n\n**Original source:** A class report says: ''Our school garden has four raised beds. Last Tuesday, students saw nine bees, seven butterflies and two dragonflies.''\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** Caption: ''Number of three insect types seen in our garden on Tuesday.'' Not: ''Bees always outnumber butterflies everywhere.''\n\n**GUIDED TRY:** Guided: A recycling club records paper 12, cans 5 and bottles 8. Select a bar chart, label a 0–12 count scale, choose a caption and write one accurate comparison. Feedback: Paper has the highest recorded count, but the data do not establish which material is most recycled across Australia.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"A caption explains what the reader sees and can connect it to the report. Avoid extending a one-day survey to every day.","check":{"question":"Which Tuesday sighting is highest?","options":["Bees: 9","Butterflies: 7","Dragonflies: 2","All equal"],"correct_index":0,"explanation":"Bees: 9. Caption: ''Number of three insect types seen in our garden on Tuesday.'' Not: ''Bees always outnumber butterflies everywhere.''"}},{"icon":"✅","title":"Write the report around the visual","explain":"**Learn:** A visual supports sentences but does not replace an introduction, explanatory paragraph or careful conclusion.\n\n**Original source:** A class report says: ''Our school garden has four raised beds. Last Tuesday, students saw nine bees, seven butterflies and two dragonflies.''\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** I write: ''Our class counted nine bees, seven butterflies and two dragonflies on Tuesday. The bar chart compares these observations.''\n\n**GUIDED TRY:** Guided: A recycling club records paper 12, cans 5 and bottles 8. Select a bar chart, label a 0–12 count scale, choose a caption and write one accurate comparison. Feedback: Paper has the highest recorded count, but the data do not establish which material is most recycled across Australia.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"A visual supports sentences but does not replace an introduction, explanatory paragraph or careful conclusion.","check":{"question":"Which caption is accurate?","options":["Tuesday garden observations","Every bee in Australia","All gardens are identical","Insects never change"],"correct_index":0,"explanation":"Tuesday garden observations. I write: ''Our class counted nine bees, seven butterflies and two dragonflies on Tuesday. The bar chart compares these observations.''"}}],"worked_example":"## Teacher model\n\nA class report says: ''Our school garden has four raised beds. Last Tuesday, students saw nine bees, seven butterflies and two dragonflies.''\n\n**1. Match the visual to the information:** To compare bee, butterfly and dragonfly sightings, I choose a bar chart, not a drawing of one large bee.\n\n**2. Give the visual accurate labels:** Title: Insects Seen on Tuesday. Bars: bees 9, butterflies 7, dragonflies 2. The scale counts sightings from zero.\n\n**3. Use a caption that stays within the evidence:** Caption: ''Number of three insect types seen in our garden on Tuesday.'' Not: ''Bees always outnumber butterflies everywhere.''\n\n**4. Write the report around the visual:** I write: ''Our class counted nine bees, seven butterflies and two dragonflies on Tuesday. The bar chart compares these observations.''\n\n**Check:** Explain one decision without copying the model.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 610 185\"><rect width=\"610\" height=\"185\" rx=\"12\" fill=\"#f2f7f3\"/><text x=\"14\" y=\"29\" font-family=\"Arial\" font-size=\"19\" fill=\"#214333\">Information Reports: Make Visuals Work</text><rect x=\"10\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#deeee3\"/><text x=\"17\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Match the visual</text><rect x=\"161\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#e7ebfa\"/><text x=\"168\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Give the visual </text><rect x=\"312\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#deeee3\"/><text x=\"319\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Use a caption th</text><rect x=\"463\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#e7ebfa\"/><text x=\"470\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Write the report</text></svg>","alt":"Four-step learning guide for Information Reports: Make Visuals Work","caption":"Use the examples to investigate each concept."}],"guided_practice":"Guided: A recycling club records paper 12, cans 5 and bottles 8. Select a bar chart, label a 0–12 count scale, choose a caption and write one accurate comparison. Feedback: Paper has the highest recorded count, but the data do not establish which material is most recycled across Australia.","independent_task":"Prepare a 120–160-word factual mini-report about a fictional garden survey: ladybirds 6, bees 11, butterflies 8, dragonflies 3. Include a title, introduction, two factual paragraphs, one labelled bar-chart plan or typed bar chart, a precise caption and a concluding sentence. Answer which group has most, fewest and the difference. Explain one claim the survey cannot support.","response_prompt":"Complete the information reports: make visuals work task independently, showing evidence or working.","quiz":[{"type":"multiple_choice","question":"Which visual best compares four counts?","options":["Bar chart","Single animal portrait","Map of Australia","Clock"],"correct_index":0,"explanation":"Bar chart follows the original example and reasoning."},{"type":"multiple_choice","question":"What must the vertical chart scale show?","options":["Counts","Only colours","The author''s favourite insect","No units"],"correct_index":0,"explanation":"Counts follows the original example and reasoning."},{"type":"multiple_choice","question":"Which Tuesday sighting is highest?","options":["Bees: 9","Butterflies: 7","Dragonflies: 2","All equal"],"correct_index":0,"explanation":"Bees: 9 follows the original example and reasoning."},{"type":"multiple_choice","question":"Which caption is accurate?","options":["Tuesday garden observations","Every bee in Australia","All gardens are identical","Insects never change"],"correct_index":0,"explanation":"Tuesday garden observations follows the original example and reasoning."},{"type":"multiple_choice","question":"How many more bees than dragonflies were seen?","options":["5","6","7","8"],"correct_index":2,"explanation":"7 follows the original example and reasoning."},{"type":"multiple_choice","question":"Why include a caption?","options":["Explain the visual in context","Hide the data","Replace source evidence","Add unrelated stories"],"correct_index":0,"explanation":"Explain the visual in context follows the original example and reasoning."},{"type":"multiple_choice","question":"Which is unsupported?","options":["Nine bees were recorded","Two dragonflies were recorded","Bees always outnumber other insects","Seven butterflies were recorded"],"correct_index":2,"explanation":"Bees always outnumber other insects follows the original example and reasoning."},{"type":"multiple_choice","question":"What is essential besides the chart?","options":["Clear explanatory report sentences","Only decoration","No heading","Invented conclusions"],"correct_index":0,"explanation":"Clear explanatory report sentences follows the original example and reasoning."},{"type":"short_answer","question":"Complete the original independent information reports: make visuals work challenge.","sample_answer":"Mini-report: Our Garden Insect Survey. During one fictional garden observation, the class counted four insect types. Bees were observed 11 times, butterflies 8 times, ladybirds 6 times and dragonflies 3 times. A bar chart with a zero-based count scale shows those four values. Caption: ''Counts of four insect types during one class garden survey.'' Bees were the most numerous recorded type and dragonflies the fewest, with a difference of eight.","marking_guide":"Require complete topic-specific accurate work and supporting reasoning.","explanation":"A strong answer justifies its conclusions."},{"type":"short_answer","question":"Explain a meaningful check, improvement or limitation for information reports: make visuals work.","sample_answer":"The chart cannot show that every garden has more bees than dragonflies. Its values describe only the supplied observation. My labels give categories and numbers, and the caption states the setting.","marking_guide":"Require complete topic-specific accurate work and supporting reasoning.","explanation":"A strong answer justifies its conclusions."}],"parent_notes":"Parent: Ask for an independent student attempt and a verbal or written explanation before using models.\n\nParent: **Written model answer 1:** Mini-report: Our Garden Insect Survey. During one fictional garden observation, the class counted four insect types. Bees were observed 11 times, butterflies 8 times, ladybirds 6 times and dragonflies 3 times. A bar chart with a zero-based count scale shows those four values. Caption: ''Counts of four insect types during one class garden survey.'' Bees were the most numerous recorded type and dragonflies the fewest, with a difference of eight.\n\nParent: **Written model answer 2:** The chart cannot show that every garden has more bees than dragonflies. Its values describe only the supplied observation. My labels give categories and numbers, and the caption states the setting.\n\nParent: Keep authentic evidence and assess the written answers. Formal NESA mapping remains to be checked.","evidence_instructions":"Keep the guided information reports: make visuals work practice, independent work, one correction and both written quiz answers.","offline_alternative":"Complete the original information and tasks on paper and retain student work.","extension":"Invent a new information reports: make visuals work example and explain its answer.","stage_hints":{"accept":["Review the Information Reports: Make Visuals Work instructions.","Find a particular number or source phrase connected to information reports: make visuals work.","Explain the evidence or calculation and check for an error."],"teach0":["Review the Match the visual to the information instructions.","Find a particular number or source phrase connected to match the visual to the information.","Explain the evidence or calculation and check for an error."],"teach1":["Review the Give the visual accurate labels instructions.","Find a particular number or source phrase connected to give the visual accurate labels.","Explain the evidence or calculation and check for an error."],"teach2":["Review the Use a caption that stays within the evidence instructions.","Find a particular number or source phrase connected to use a caption that stays within the evidence.","Explain the evidence or calculation and check for an error."],"teach3":["Review the Write the report around the visual instructions.","Find a particular number or source phrase connected to write the report around the visual.","Explain the evidence or calculation and check for an error."],"learn":["Review the Information Reports: Make Visuals Work instructions.","Find a particular number or source phrase connected to information reports: make visuals work.","Explain the evidence or calculation and check for an error."],"guided":["Review the Information Reports: Make Visuals Work instructions.","Find a particular number or source phrase connected to information reports: make visuals work.","Explain the evidence or calculation and check for an error."],"write":["Review the Information Reports: Make Visuals Work instructions.","Find a particular number or source phrase connected to information reports: make visuals work.","Explain the evidence or calculation and check for an error."],"quiz":["Review the Information Reports: Make Visuals Work instructions.","Find a particular number or source phrase connected to information reports: make visuals work.","Explain the evidence or calculation and check for an error."],"submit":["Review the Information Reports: Make Visuals Work instructions.","Find a particular number or source phrase connected to information reports: make visuals work.","Explain the evidence or calculation and check for an error."]}}') WHERE seed_key='s2-eng-y3-w09-l2';

UPDATE lessons SET title='Sentence Connections: Compound or Complex?',data=json_patch(data,'{"seed_key":"s2-eng-y3-w09-l3","title":"Sentence Connections: Compound or Complex?","stage":"Stage 2","learning_area":"English","year_level":3,"week":9,"lesson_number":3,"duration_minutes":60,"child_mission":"Learn sentence connections: compound or complex? through explicit examples, guided work and an independent task.","learning_intention":"We are learning to apply sentence connections: compound or complex? accurately and explain our choices.","success_criteria":["I can explain the central idea.","I can work through four taught concepts.","I can practise using supportive feedback.","I can complete an original independent task.","I can check my work and explain one improvement."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"The four learning concepts","cards":[{"front":"Recognise two independent clauses","back":"A compound sentence often joins two complete independent clauses with a coordinating conjunction such as and, but or so."},{"front":"Use a coordinating conjunction meaningfully","back":"And adds, but contrasts, and so can show a result. Select the connector that expresses the real relationship."},{"front":"Recognise dependent clauses","back":"A complex sentence links a main clause with a dependent clause using words such as because, when or although."},{"front":"Check punctuation and avoid fragments","back":"A dependent clause first is generally followed by a comma; two independent clauses linked with and, but or so often take a comma."}]}],"printable_resource":{"title":"Sentence Connections: Compound or Complex?","instructions":"Read the source and teacher model, attempt guided practice and then your independent challenge.","passage":"''The clouds gathered, and the wind rose.'' ''We went inside because rain began.''","prompts":["What does the source show?","Which method or text feature helps?","Complete your own response.","Explain how you checked."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Recognise two independent clauses","explain":"**Learn:** A compound sentence often joins two complete independent clauses with a coordinating conjunction such as and, but or so.\n\n**Original source:** ''The clouds gathered, and the wind rose.'' ''We went inside because rain began.''\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** ''The clouds gathered'' and ''the wind rose'' can each stand alone. Together: ''The clouds gathered, and the wind rose.''\n\n**GUIDED TRY:** Guided: Combine ''The gate opened. We entered.'' using and: ''The gate opened, and we entered.'' Combine ''The class stayed indoors. A storm began.'' using because: ''The class stayed indoors because a storm began.'' Combine ''The puzzle was difficult. Sam finished it.'' using although: ''Although the puzzle was difficult, Sam finished it.'' Identify the independent clause in each.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"A compound sentence often joins two complete independent clauses with a coordinating conjunction such as and, but or so.","check":{"question":"Which contains two independent clauses?","options":["The clouds gathered, and the wind rose.","Because it rained.","When the bell rang.","Although it was cold."],"correct_index":0,"explanation":"The clouds gathered, and the wind rose.. ''The clouds gathered'' and ''the wind rose'' can each stand alone. Together: ''The clouds gathered, and the wind rose.''"},"visual_before":[{"episode":{"title":"Investigating Sentence Connections: Compound or Complex?","transcript":"Pip: The clouds gathered and the wind rose. Can both parts stand alone?\nJuno: Yes, so they are independent clauses joined into a compound sentence.\nPip: Because rain began cannot stand alone. It needs a main clause.\nJuno: Pause and make a complete complex sentence using because.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"The clouds gathered and the wind rose. Can both parts stand alone?"},{"who":"juno","text":"Yes, so they are independent clauses joined into a compound sentence."},{"who":"pip","text":"Because rain began cannot stand alone. It needs a main clause."},{"who":"juno","text":"Pause and make a complete complex sentence using because.","pause_after":true}]}]}}]},{"icon":"📖","title":"Use a coordinating conjunction meaningfully","explain":"**Learn:** And adds, but contrasts, and so can show a result. Select the connector that expresses the real relationship.\n\n**Original source:** ''The clouds gathered, and the wind rose.'' ''We went inside because rain began.''\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** ''The field was wet, so the match was postponed'' shows result. ''The field was wet, but the match continued'' shows contrast.\n\n**GUIDED TRY:** Guided: Combine ''The gate opened. We entered.'' using and: ''The gate opened, and we entered.'' Combine ''The class stayed indoors. A storm began.'' using because: ''The class stayed indoors because a storm began.'' Combine ''The puzzle was difficult. Sam finished it.'' using although: ''Although the puzzle was difficult, Sam finished it.'' Identify the independent clause in each.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"And adds, but contrasts, and so can show a result. Select the connector that expresses the real relationship.","check":{"question":"Which conjunction usually shows contrast?","options":["but","and","because","when"],"correct_index":0,"explanation":"but. ''The field was wet, so the match was postponed'' shows result. ''The field was wet, but the match continued'' shows contrast."}},{"icon":"✏️","title":"Recognise dependent clauses","explain":"**Learn:** A complex sentence links a main clause with a dependent clause using words such as because, when or although.\n\n**Original source:** ''The clouds gathered, and the wind rose.'' ''We went inside because rain began.''\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** ''Because rain began'' is dependent and incomplete alone. ''We went inside because rain began'' is complete.\n\n**GUIDED TRY:** Guided: Combine ''The gate opened. We entered.'' using and: ''The gate opened, and we entered.'' Combine ''The class stayed indoors. A storm began.'' using because: ''The class stayed indoors because a storm began.'' Combine ''The puzzle was difficult. Sam finished it.'' using although: ''Although the puzzle was difficult, Sam finished it.'' Identify the independent clause in each.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"A complex sentence links a main clause with a dependent clause using words such as because, when or although.","check":{"question":"Which can introduce a reason?","options":["because","but","and","or"],"correct_index":0,"explanation":"because. ''Because rain began'' is dependent and incomplete alone. ''We went inside because rain began'' is complete."}},{"icon":"✅","title":"Check punctuation and avoid fragments","explain":"**Learn:** A dependent clause first is generally followed by a comma; two independent clauses linked with and, but or so often take a comma.\n\n**Original source:** ''The clouds gathered, and the wind rose.'' ''We went inside because rain began.''\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** ''When the bell rang, the class lined up.'' ''The bell rang, and the class lined up.'' I check both verbs and the relationship.\n\n**GUIDED TRY:** Guided: Combine ''The gate opened. We entered.'' using and: ''The gate opened, and we entered.'' Combine ''The class stayed indoors. A storm began.'' using because: ''The class stayed indoors because a storm began.'' Combine ''The puzzle was difficult. Sam finished it.'' using although: ''Although the puzzle was difficult, Sam finished it.'' Identify the independent clause in each.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"A dependent clause first is generally followed by a comma; two independent clauses linked with and, but or so often take a comma.","check":{"question":"Which is a dependent-clause fragment?","options":["Because rain began.","We went inside.","The bell rang.","The birds called."],"correct_index":0,"explanation":"Because rain began.. ''When the bell rang, the class lined up.'' ''The bell rang, and the class lined up.'' I check both verbs and the relationship."}}],"worked_example":"## Teacher model\n\n''The clouds gathered, and the wind rose.'' ''We went inside because rain began.''\n\n**1. Recognise two independent clauses:** ''The clouds gathered'' and ''the wind rose'' can each stand alone. Together: ''The clouds gathered, and the wind rose.''\n\n**2. Use a coordinating conjunction meaningfully:** ''The field was wet, so the match was postponed'' shows result. ''The field was wet, but the match continued'' shows contrast.\n\n**3. Recognise dependent clauses:** ''Because rain began'' is dependent and incomplete alone. ''We went inside because rain began'' is complete.\n\n**4. Check punctuation and avoid fragments:** ''When the bell rang, the class lined up.'' ''The bell rang, and the class lined up.'' I check both verbs and the relationship.\n\n**Check:** Explain one decision without copying the model.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 610 185\"><rect width=\"610\" height=\"185\" rx=\"12\" fill=\"#f2f7f3\"/><text x=\"14\" y=\"29\" font-family=\"Arial\" font-size=\"19\" fill=\"#214333\">Sentence Connections: Compound or Complex?</text><rect x=\"10\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#deeee3\"/><text x=\"17\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Recognise two in</text><rect x=\"161\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#e7ebfa\"/><text x=\"168\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Use a coordinati</text><rect x=\"312\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#deeee3\"/><text x=\"319\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Recognise depend</text><rect x=\"463\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#e7ebfa\"/><text x=\"470\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Check punctuatio</text></svg>","alt":"Four-step learning guide for Sentence Connections: Compound or Complex?","caption":"Use the examples to investigate each concept."}],"guided_practice":"Guided: Combine ''The gate opened. We entered.'' using and: ''The gate opened, and we entered.'' Combine ''The class stayed indoors. A storm began.'' using because: ''The class stayed indoors because a storm began.'' Combine ''The puzzle was difficult. Sam finished it.'' using although: ''Although the puzzle was difficult, Sam finished it.'' Identify the independent clause in each.","independent_task":"Create six original sentences about a garden working bee: three compound (using and, but and so) and three complex (using because, when and although). Underline the independent clauses and bracket dependent clauses. Explain the meaning of two connectors, revise the fragment ''When the rain stopped.'' and correct a comma mistake.","response_prompt":"Complete the sentence connections: compound or complex? task independently, showing evidence or working.","quiz":[{"type":"multiple_choice","question":"Which contains two independent clauses?","options":["The clouds gathered, and the wind rose.","Because it rained.","When the bell rang.","Although it was cold."],"correct_index":0,"explanation":"The clouds gathered, and the wind rose. follows the original example and reasoning."},{"type":"multiple_choice","question":"Which conjunction usually shows contrast?","options":["but","and","because","when"],"correct_index":0,"explanation":"but follows the original example and reasoning."},{"type":"multiple_choice","question":"Which can introduce a reason?","options":["because","but","and","or"],"correct_index":0,"explanation":"because follows the original example and reasoning."},{"type":"multiple_choice","question":"Which is a dependent-clause fragment?","options":["Because rain began.","We went inside.","The bell rang.","The birds called."],"correct_index":0,"explanation":"Because rain began. follows the original example and reasoning."},{"type":"multiple_choice","question":"Which is correctly punctuated?","options":["When the bell rang, we lined up.","When, the bell rang we lined up.","When the bell rang we, lined up.","When the, bell rang."],"correct_index":0,"explanation":"When the bell rang, we lined up. follows the original example and reasoning."},{"type":"multiple_choice","question":"Which sentence uses so for a result?","options":["The path flooded, so we turned back.","The path flooded, but we walked.","We returned because it flooded.","When it flooded, we left."],"correct_index":0,"explanation":"The path flooded, so we turned back. follows the original example and reasoning."},{"type":"multiple_choice","question":"Main clause in ''Although it rained, we walked''?","options":["We walked","Although it rained","Although","It rained"],"correct_index":0,"explanation":"We walked follows the original example and reasoning."},{"type":"multiple_choice","question":"Which completes the fragment?","options":["When the rain stopped, we resumed the game.","When the rain stopped.","When rain.","Stopped when."],"correct_index":0,"explanation":"When the rain stopped, we resumed the game. follows the original example and reasoning."},{"type":"short_answer","question":"Complete the original independent sentence connections: compound or complex? challenge.","sample_answer":"Compound: The volunteers arrived, and they picked up tools. The soil was dry, but the paths were wet. The rain started, so the team moved indoors. Complex: We brought gloves because the ground was rough. When the clouds cleared, we resumed planting. Although the task was difficult, we finished it.","marking_guide":"Require complete topic-specific accurate work and supporting reasoning.","explanation":"A strong answer justifies its conclusions."},{"type":"short_answer","question":"Explain a meaningful check, improvement or limitation for sentence connections: compound or complex?.","sample_answer":"''But'' signals contrast and ''because'' provides a reason. ''When the rain stopped, we continued working'' fixes the fragment by adding the main clause. I used a comma after an introductory when-clause.","marking_guide":"Require complete topic-specific accurate work and supporting reasoning.","explanation":"A strong answer justifies its conclusions."}],"parent_notes":"Parent: Ask for an independent student attempt and a verbal or written explanation before using models.\n\nParent: **Written model answer 1:** Compound: The volunteers arrived, and they picked up tools. The soil was dry, but the paths were wet. The rain started, so the team moved indoors. Complex: We brought gloves because the ground was rough. When the clouds cleared, we resumed planting. Although the task was difficult, we finished it.\n\nParent: **Written model answer 2:** ''But'' signals contrast and ''because'' provides a reason. ''When the rain stopped, we continued working'' fixes the fragment by adding the main clause. I used a comma after an introductory when-clause.\n\nParent: Keep authentic evidence and assess the written answers. Formal NESA mapping remains to be checked.","evidence_instructions":"Keep the guided sentence connections: compound or complex? practice, independent work, one correction and both written quiz answers.","offline_alternative":"Complete the original information and tasks on paper and retain student work.","extension":"Invent a new sentence connections: compound or complex? example and explain its answer.","stage_hints":{"accept":["Review the Sentence Connections: Compound or Complex? instructions.","Find a particular number or source phrase connected to sentence connections: compound or complex?.","Explain the evidence or calculation and check for an error."],"teach0":["Review the Recognise two independent clauses instructions.","Find a particular number or source phrase connected to recognise two independent clauses.","Explain the evidence or calculation and check for an error."],"teach1":["Review the Use a coordinating conjunction meaningfully instructions.","Find a particular number or source phrase connected to use a coordinating conjunction meaningfully.","Explain the evidence or calculation and check for an error."],"teach2":["Review the Recognise dependent clauses instructions.","Find a particular number or source phrase connected to recognise dependent clauses.","Explain the evidence or calculation and check for an error."],"teach3":["Review the Check punctuation and avoid fragments instructions.","Find a particular number or source phrase connected to check punctuation and avoid fragments.","Explain the evidence or calculation and check for an error."],"learn":["Review the Sentence Connections: Compound or Complex? instructions.","Find a particular number or source phrase connected to sentence connections: compound or complex?.","Explain the evidence or calculation and check for an error."],"guided":["Review the Sentence Connections: Compound or Complex? instructions.","Find a particular number or source phrase connected to sentence connections: compound or complex?.","Explain the evidence or calculation and check for an error."],"write":["Review the Sentence Connections: Compound or Complex? instructions.","Find a particular number or source phrase connected to sentence connections: compound or complex?.","Explain the evidence or calculation and check for an error."],"quiz":["Review the Sentence Connections: Compound or Complex? instructions.","Find a particular number or source phrase connected to sentence connections: compound or complex?.","Explain the evidence or calculation and check for an error."],"submit":["Review the Sentence Connections: Compound or Complex? instructions.","Find a particular number or source phrase connected to sentence connections: compound or complex?.","Explain the evidence or calculation and check for an error."]}}') WHERE seed_key='s2-eng-y3-w09-l3';

UPDATE lessons SET title='Clear Labels: Handwriting for Diagrams and Captions',data=json_patch(data,'{"seed_key":"s2-eng-y3-w09-l4","title":"Clear Labels: Handwriting for Diagrams and Captions","stage":"Stage 2","learning_area":"English","year_level":3,"week":9,"lesson_number":4,"duration_minutes":60,"child_mission":"Learn clear labels: handwriting for diagrams and captions through explicit examples, guided work and an independent task.","learning_intention":"We are learning to apply clear labels: handwriting for diagrams and captions accurately and explain our choices.","success_criteria":["I can explain the central idea.","I can work through four taught concepts.","I can practise using supportive feedback.","I can complete an original independent task.","I can check my work and explain one improvement."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"The four learning concepts","cards":[{"front":"Identify what must be labelled","back":"A good diagram label names a specific part. A caption explains what the whole diagram shows. They have different jobs."},{"front":"Use clear spacing and letter shapes","back":"Label writing must be large enough to read, with distinguishable letters and spaces. Straight leader lines can connect words to parts without crossing."},{"front":"Write a useful caption","back":"A caption should accurately identify what the diagram represents, not restate one label or invent a function."},{"front":"Review readability and accessibility","back":"Ask someone to identify each label without hints. Revise spacing or use typed labels if writing is difficult; clarity is the goal."}]}],"printable_resource":{"title":"Clear Labels: Handwriting for Diagrams and Captions","instructions":"Read the source and teacher model, attempt guided practice and then your independent challenge.","passage":"A student draws a plant diagram with roots, stem, leaves and flower. The labels overlap and the caption is difficult to read.","prompts":["What does the source show?","Which method or text feature helps?","Complete your own response.","Explain how you checked."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Identify what must be labelled","explain":"**Learn:** A good diagram label names a specific part. A caption explains what the whole diagram shows. They have different jobs.\n\n**Original source:** A student draws a plant diagram with roots, stem, leaves and flower. The labels overlap and the caption is difficult to read.\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** ''Roots'' points to the underground part; ''Stem'' to the supporting stalk. Caption: ''Main parts of a flowering plant.''\n\n**GUIDED TRY:** Guided: Sketch a labelled water cycle with arrows for evaporation, condensation and precipitation. Keep labels outside crowded arrows and add the caption ''Simplified stages of the water cycle''. Ask a reader to match each label to the appropriate part; revise any confusing line. Typed and handwritten labels are equally valid for the evidence.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"A good diagram label names a specific part. A caption explains what the whole diagram shows. They have different jobs.","check":{"question":"What does a diagram label do?","options":["Names a specific part","Explains every paragraph","Replaces a picture","Introduces a story villain"],"correct_index":0,"explanation":"Names a specific part. ''Roots'' points to the underground part; ''Stem'' to the supporting stalk. Caption: ''Main parts of a flowering plant.''"},"visual_before":[{"episode":{"title":"Investigating Clear Labels: Handwriting for Diagrams and Captions","transcript":"Pip: My plant labels are squeezed into the petals. No one can read them!\nJuno: Move the words into clear space and connect them with leader lines.\nPip: Then I''ll write a caption describing the whole diagram.\nJuno: Good. Pause and decide how to check the labels with another reader.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"My plant labels are squeezed into the petals. No one can read them!"},{"who":"juno","text":"Move the words into clear space and connect them with leader lines."},{"who":"pip","text":"Then I''ll write a caption describing the whole diagram."},{"who":"juno","text":"Good. Pause and decide how to check the labels with another reader.","pause_after":true}]}]}}]},{"icon":"📖","title":"Use clear spacing and letter shapes","explain":"**Learn:** Label writing must be large enough to read, with distinguishable letters and spaces. Straight leader lines can connect words to parts without crossing.\n\n**Original source:** A student draws a plant diagram with roots, stem, leaves and flower. The labels overlap and the caption is difficult to read.\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** I place ''flower'' outside the plant image and draw a simple line to the flower. I don''t squeeze the word inside a tiny petal.\n\n**GUIDED TRY:** Guided: Sketch a labelled water cycle with arrows for evaporation, condensation and precipitation. Keep labels outside crowded arrows and add the caption ''Simplified stages of the water cycle''. Ask a reader to match each label to the appropriate part; revise any confusing line. Typed and handwritten labels are equally valid for the evidence.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"Label writing must be large enough to read, with distinguishable letters and spaces. Straight leader lines can connect words to parts without crossing.","check":{"question":"What does a caption do?","options":["Explains the visual as a whole","Points to only one tiny part","Shows a random number","Lists every book"],"correct_index":0,"explanation":"Explains the visual as a whole. I place ''flower'' outside the plant image and draw a simple line to the flower. I don''t squeeze the word inside a tiny petal."}},{"icon":"✏️","title":"Write a useful caption","explain":"**Learn:** A caption should accurately identify what the diagram represents, not restate one label or invent a function.\n\n**Original source:** A student draws a plant diagram with roots, stem, leaves and flower. The labels overlap and the caption is difficult to read.\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** ''Parts of a flowering plant: roots, stem, leaves and flower'' is accurate. ''The plant is the best one ever'' is an opinion, not a useful scientific caption.\n\n**GUIDED TRY:** Guided: Sketch a labelled water cycle with arrows for evaporation, condensation and precipitation. Keep labels outside crowded arrows and add the caption ''Simplified stages of the water cycle''. Ask a reader to match each label to the appropriate part; revise any confusing line. Typed and handwritten labels are equally valid for the evidence.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"A caption should accurately identify what the diagram represents, not restate one label or invent a function.","check":{"question":"Which is a useful label?","options":["Roots","Lovely","Amazing","Best ever"],"correct_index":0,"explanation":"Roots. ''Parts of a flowering plant: roots, stem, leaves and flower'' is accurate. ''The plant is the best one ever'' is an opinion, not a useful scientific caption."}},{"icon":"✅","title":"Review readability and accessibility","explain":"**Learn:** Ask someone to identify each label without hints. Revise spacing or use typed labels if writing is difficult; clarity is the goal.\n\n**Original source:** A student draws a plant diagram with roots, stem, leaves and flower. The labels overlap and the caption is difficult to read.\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** If a reader mistakes ''stem'' for ''steam'', I reshape the letters or type the word, then ask them to check the corrected version.\n\n**GUIDED TRY:** Guided: Sketch a labelled water cycle with arrows for evaporation, condensation and precipitation. Keep labels outside crowded arrows and add the caption ''Simplified stages of the water cycle''. Ask a reader to match each label to the appropriate part; revise any confusing line. Typed and handwritten labels are equally valid for the evidence.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"Ask someone to identify each label without hints. Revise spacing or use typed labels if writing is difficult; clarity is the goal.","check":{"question":"Which is a useful caption?","options":["Main parts of a flowering plant","My drawing is the best","Lots of stuff","Look here!"],"correct_index":0,"explanation":"Main parts of a flowering plant. If a reader mistakes ''stem'' for ''steam'', I reshape the letters or type the word, then ask them to check the corrected version."}}],"worked_example":"## Teacher model\n\nA student draws a plant diagram with roots, stem, leaves and flower. The labels overlap and the caption is difficult to read.\n\n**1. Identify what must be labelled:** ''Roots'' points to the underground part; ''Stem'' to the supporting stalk. Caption: ''Main parts of a flowering plant.''\n\n**2. Use clear spacing and letter shapes:** I place ''flower'' outside the plant image and draw a simple line to the flower. I don''t squeeze the word inside a tiny petal.\n\n**3. Write a useful caption:** ''Parts of a flowering plant: roots, stem, leaves and flower'' is accurate. ''The plant is the best one ever'' is an opinion, not a useful scientific caption.\n\n**4. Review readability and accessibility:** If a reader mistakes ''stem'' for ''steam'', I reshape the letters or type the word, then ask them to check the corrected version.\n\n**Check:** Explain one decision without copying the model.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 610 185\"><rect width=\"610\" height=\"185\" rx=\"12\" fill=\"#f2f7f3\"/><text x=\"14\" y=\"29\" font-family=\"Arial\" font-size=\"19\" fill=\"#214333\">Clear Labels: Handwriting for Diagrams and Captions</text><rect x=\"10\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#deeee3\"/><text x=\"17\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Identify what mu</text><rect x=\"161\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#e7ebfa\"/><text x=\"168\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Use clear spacin</text><rect x=\"312\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#deeee3\"/><text x=\"319\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Write a useful c</text><rect x=\"463\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#e7ebfa\"/><text x=\"470\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Review readabili</text></svg>","alt":"Four-step learning guide for Clear Labels: Handwriting for Diagrams and Captions","caption":"Use the examples to investigate each concept."}],"guided_practice":"Guided: Sketch a labelled water cycle with arrows for evaporation, condensation and precipitation. Keep labels outside crowded arrows and add the caption ''Simplified stages of the water cycle''. Ask a reader to match each label to the appropriate part; revise any confusing line. Typed and handwritten labels are equally valid for the evidence.","independent_task":"Make a neat labelled diagram of an original garden scene including a path, garden bed, compost bin and rainwater tank. Use four readable labels and clear leader lines. Write a 12–20-word caption describing the entire picture. Produce a second version after checking spacing, accuracy and legibility; explain two changes. If handwriting is inaccessible, use typed labels and assess the same design features.","response_prompt":"Complete the clear labels: handwriting for diagrams and captions task independently, showing evidence or working.","quiz":[{"type":"multiple_choice","question":"What does a diagram label do?","options":["Names a specific part","Explains every paragraph","Replaces a picture","Introduces a story villain"],"correct_index":0,"explanation":"Names a specific part follows the original example and reasoning."},{"type":"multiple_choice","question":"What does a caption do?","options":["Explains the visual as a whole","Points to only one tiny part","Shows a random number","Lists every book"],"correct_index":0,"explanation":"Explains the visual as a whole follows the original example and reasoning."},{"type":"multiple_choice","question":"Which is a useful label?","options":["Roots","Lovely","Amazing","Best ever"],"correct_index":0,"explanation":"Roots follows the original example and reasoning."},{"type":"multiple_choice","question":"Which is a useful caption?","options":["Main parts of a flowering plant","My drawing is the best","Lots of stuff","Look here!"],"correct_index":0,"explanation":"Main parts of a flowering plant follows the original example and reasoning."},{"type":"multiple_choice","question":"Why use leader lines?","options":["Link labels to the right parts","Decorate the page only","Erase the diagram","Replace the caption"],"correct_index":0,"explanation":"Link labels to the right parts follows the original example and reasoning."},{"type":"multiple_choice","question":"How should text appear?","options":["Readable and uncrowded","Overlapping every line","Tiny and hidden","Unrelated to the drawing"],"correct_index":0,"explanation":"Readable and uncrowded follows the original example and reasoning."},{"type":"multiple_choice","question":"What is a good revision?","options":["Move a crowded label outside the diagram","Cross every leader line","Remove all spacing","Add random arrows"],"correct_index":0,"explanation":"Move a crowded label outside the diagram follows the original example and reasoning."},{"type":"multiple_choice","question":"What accessibility option is suitable?","options":["Typed labels with clear layout","No alternative","Only fast handwriting","Only pencil sketches"],"correct_index":0,"explanation":"Typed labels with clear layout follows the original example and reasoning."},{"type":"short_answer","question":"Complete the original independent clear labels: handwriting for diagrams and captions challenge.","sample_answer":"My garden diagram has distinct labels for path, garden bed, compost bin and rainwater tank. Leader lines connect the four labels to their matching features. Caption: ''A community garden layout showing places to walk, grow plants, compost waste and collect rainwater.''","marking_guide":"Require complete topic-specific accurate work and supporting reasoning.","explanation":"A strong answer justifies its conclusions."},{"type":"short_answer","question":"Explain a meaningful check, improvement or limitation for clear labels: handwriting for diagrams and captions.","sample_answer":"I moved two labels outside the drawing so the words no longer overlap, and I adjusted a leader line to point clearly at the tank. A reader could identify all four features without prompting.","marking_guide":"Require complete topic-specific accurate work and supporting reasoning.","explanation":"A strong answer justifies its conclusions."}],"parent_notes":"Parent: Ask for an independent student attempt and a verbal or written explanation before using models.\n\nParent: **Written model answer 1:** My garden diagram has distinct labels for path, garden bed, compost bin and rainwater tank. Leader lines connect the four labels to their matching features. Caption: ''A community garden layout showing places to walk, grow plants, compost waste and collect rainwater.''\n\nParent: **Written model answer 2:** I moved two labels outside the drawing so the words no longer overlap, and I adjusted a leader line to point clearly at the tank. A reader could identify all four features without prompting.\n\nParent: Keep authentic evidence and assess the written answers. Formal NESA mapping remains to be checked.","evidence_instructions":"Keep the guided clear labels: handwriting for diagrams and captions practice, independent work, one correction and both written quiz answers.","offline_alternative":"Complete the original information and tasks on paper and retain student work.","extension":"Invent a new clear labels: handwriting for diagrams and captions example and explain its answer.","stage_hints":{"accept":["Review the Clear Labels: Handwriting for Diagrams and Captions instructions.","Find a particular number or source phrase connected to clear labels: handwriting for diagrams and captions.","Explain the evidence or calculation and check for an error."],"teach0":["Review the Identify what must be labelled instructions.","Find a particular number or source phrase connected to identify what must be labelled.","Explain the evidence or calculation and check for an error."],"teach1":["Review the Use clear spacing and letter shapes instructions.","Find a particular number or source phrase connected to use clear spacing and letter shapes.","Explain the evidence or calculation and check for an error."],"teach2":["Review the Write a useful caption instructions.","Find a particular number or source phrase connected to write a useful caption.","Explain the evidence or calculation and check for an error."],"teach3":["Review the Review readability and accessibility instructions.","Find a particular number or source phrase connected to review readability and accessibility.","Explain the evidence or calculation and check for an error."],"learn":["Review the Clear Labels: Handwriting for Diagrams and Captions instructions.","Find a particular number or source phrase connected to clear labels: handwriting for diagrams and captions.","Explain the evidence or calculation and check for an error."],"guided":["Review the Clear Labels: Handwriting for Diagrams and Captions instructions.","Find a particular number or source phrase connected to clear labels: handwriting for diagrams and captions.","Explain the evidence or calculation and check for an error."],"write":["Review the Clear Labels: Handwriting for Diagrams and Captions instructions.","Find a particular number or source phrase connected to clear labels: handwriting for diagrams and captions.","Explain the evidence or calculation and check for an error."],"quiz":["Review the Clear Labels: Handwriting for Diagrams and Captions instructions.","Find a particular number or source phrase connected to clear labels: handwriting for diagrams and captions.","Explain the evidence or calculation and check for an error."],"submit":["Review the Clear Labels: Handwriting for Diagrams and Captions instructions.","Find a particular number or source phrase connected to clear labels: handwriting for diagrams and captions.","Explain the evidence or calculation and check for an error."]}}') WHERE seed_key='s2-eng-y3-w09-l4';

UPDATE lessons SET title='Array Architects: Rows, Columns and Equal Groups',data=json_patch(data,'{"seed_key":"s2-mat-y3-w09-l1","title":"Array Architects: Rows, Columns and Equal Groups","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":9,"lesson_number":1,"duration_minutes":60,"child_mission":"Learn array architects: rows, columns and equal groups through explicit examples, guided work and an independent task.","learning_intention":"We are learning to apply array architects: rows, columns and equal groups accurately and explain our choices.","success_criteria":["I can explain the central idea.","I can work through four taught concepts.","I can practise using supportive feedback.","I can complete an original independent task.","I can check my work and explain one improvement."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"The four learning concepts","cards":[{"front":"See rows and equal groups","back":"An array arranges objects in equal rows and columns. You can count the rows and items per row to find the total."},{"front":"Connect arrays to multiplication","back":"Multiplication describes equal groups efficiently. Make clear what each factor represents."},{"front":"Rotate an array and observe","back":"Turning the array changes how we describe rows and columns but not the number of objects."},{"front":"Distinguish equal and unequal groups","back":"An unequal set of rows is not a rectangular array until every row has the same number. Count carefully instead of guessing."}]}],"printable_resource":{"title":"Array Architects: Rows, Columns and Equal Groups","instructions":"Read the source and teacher model, attempt guided practice and then your independent challenge.","passage":"At the fair, chairs are arranged in three rows with four chairs in each row.","prompts":["What does the source show?","Which method or text feature helps?","Complete your own response.","Explain how you checked."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"See rows and equal groups","explain":"**Learn:** An array arranges objects in equal rows and columns. You can count the rows and items per row to find the total.\n\n**Original source:** At the fair, chairs are arranged in three rows with four chairs in each row.\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** Three rows of four chairs = 4+4+4=12 chairs. I draw three horizontal rows, each with four dots.\n\n**GUIDED TRY:** Guided: Draw 4 rows of 5 dots. Count by fives: 5+5+5+5=20, so 4×5=20. Turn the sketch mentally into 5 rows of 4 and check 5×4=20. Try 2 rows of 6: 6+6=12. Spot the error: 3 rows of 5, 5 and 4 have 14, not 15.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"An array arranges objects in equal rows and columns. You can count the rows and items per row to find the total.","check":{"question":"3 rows of 4?","options":["7","11","12","16"],"correct_index":2,"explanation":"12. Three rows of four chairs = 4+4+4=12 chairs. I draw three horizontal rows, each with four dots."},"visual_before":[{"episode":{"title":"Investigating Array Architects: Rows, Columns and Equal Groups","transcript":"Pip: I arranged three rows of four chairs. Do I have seven chairs?\nJuno: Count the equal groups: four plus four plus four.\nPip: That''s twelve, which I can write as three times four.\nJuno: Pause and imagine rotating the arrangement. How many chairs now?","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I arranged three rows of four chairs. Do I have seven chairs?"},{"who":"juno","text":"Count the equal groups: four plus four plus four."},{"who":"pip","text":"That''s twelve, which I can write as three times four."},{"who":"juno","text":"Pause and imagine rotating the arrangement. How many chairs now?","pause_after":true}]}]}}]},{"icon":"📖","title":"Connect arrays to multiplication","explain":"**Learn:** Multiplication describes equal groups efficiently. Make clear what each factor represents.\n\n**Original source:** At the fair, chairs are arranged in three rows with four chairs in each row.\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** 3×4=12: three rows, four items in each row. Both factors describe the same array.\n\n**GUIDED TRY:** Guided: Draw 4 rows of 5 dots. Count by fives: 5+5+5+5=20, so 4×5=20. Turn the sketch mentally into 5 rows of 4 and check 5×4=20. Try 2 rows of 6: 6+6=12. Spot the error: 3 rows of 5, 5 and 4 have 14, not 15.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"Multiplication describes equal groups efficiently. Make clear what each factor represents.","check":{"question":"Which repeated sum is 3×4?","options":["4+4+4","3+4","3+3+3","4+3+4+3"],"correct_index":0,"explanation":"4+4+4. 3×4=12: three rows, four items in each row. Both factors describe the same array."}},{"icon":"✏️","title":"Rotate an array and observe","explain":"**Learn:** Turning the array changes how we describe rows and columns but not the number of objects.\n\n**Original source:** At the fair, chairs are arranged in three rows with four chairs in each row.\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** A 3-by-4 array has 12; turning it creates a 4-by-3 array, also 12. This models 3×4=4×3.\n\n**GUIDED TRY:** Guided: Draw 4 rows of 5 dots. Count by fives: 5+5+5+5=20, so 4×5=20. Turn the sketch mentally into 5 rows of 4 and check 5×4=20. Try 2 rows of 6: 6+6=12. Spot the error: 3 rows of 5, 5 and 4 have 14, not 15.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"Turning the array changes how we describe rows and columns but not the number of objects.","check":{"question":"4 rows of 5?","options":["9","15","20","25"],"correct_index":2,"explanation":"20. A 3-by-4 array has 12; turning it creates a 4-by-3 array, also 12. This models 3×4=4×3."}},{"icon":"✅","title":"Distinguish equal and unequal groups","explain":"**Learn:** An unequal set of rows is not a rectangular array until every row has the same number. Count carefully instead of guessing.\n\n**Original source:** At the fair, chairs are arranged in three rows with four chairs in each row.\n\n**Notice:** Identify the exact evidence supporting this idea.","example":"**WATCH MY THINKING:** Rows of four, four and three total 11, not 12. You cannot call that a 3×4 rectangle because one spot is missing.\n\n**GUIDED TRY:** Guided: Draw 4 rows of 5 dots. Count by fives: 5+5+5+5=20, so 4×5=20. Turn the sketch mentally into 5 rows of 4 and check 5×4=20. Try 2 rows of 6: 6+6=12. Spot the error: 3 rows of 5, 5 and 4 have 14, not 15.\n\n**CHECK:** Explain how your method works and identify a possible mistake.","notice":"An unequal set of rows is not a rectangular array until every row has the same number. Count carefully instead of guessing.","check":{"question":"5 rows of 4?","options":["10","15","20","25"],"correct_index":2,"explanation":"20. Rows of four, four and three total 11, not 12. You cannot call that a 3×4 rectangle because one spot is missing."}}],"worked_example":"## Teacher model\n\nAt the fair, chairs are arranged in three rows with four chairs in each row.\n\n**1. See rows and equal groups:** Three rows of four chairs = 4+4+4=12 chairs. I draw three horizontal rows, each with four dots.\n\n**2. Connect arrays to multiplication:** 3×4=12: three rows, four items in each row. Both factors describe the same array.\n\n**3. Rotate an array and observe:** A 3-by-4 array has 12; turning it creates a 4-by-3 array, also 12. This models 3×4=4×3.\n\n**4. Distinguish equal and unequal groups:** Rows of four, four and three total 11, not 12. You cannot call that a 3×4 rectangle because one spot is missing.\n\n**Check:** Explain one decision without copying the model.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 610 185\"><rect width=\"610\" height=\"185\" rx=\"12\" fill=\"#f2f7f3\"/><text x=\"14\" y=\"29\" font-family=\"Arial\" font-size=\"19\" fill=\"#214333\">Array Architects: Rows, Columns and Equal Groups</text><rect x=\"10\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#deeee3\"/><text x=\"17\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">See rows and equ</text><rect x=\"161\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#e7ebfa\"/><text x=\"168\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Connect arrays t</text><rect x=\"312\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#deeee3\"/><text x=\"319\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Rotate an array </text><rect x=\"463\" y=\"60\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#e7ebfa\"/><text x=\"470\" y=\"113\" font-family=\"Arial\" font-size=\"12\" fill=\"#243f31\">Distinguish equa</text></svg>","alt":"Four-step learning guide for Array Architects: Rows, Columns and Equal Groups","caption":"Use the examples to investigate each concept."}],"guided_practice":"Guided: Draw 4 rows of 5 dots. Count by fives: 5+5+5+5=20, so 4×5=20. Turn the sketch mentally into 5 rows of 4 and check 5×4=20. Try 2 rows of 6: 6+6=12. Spot the error: 3 rows of 5, 5 and 4 have 14, not 15.","independent_task":"**Market stall arrays:** Make diagrams for 5 rows of 4 plants, 3 rows of 7 seed packets and 6 rows of 2 pots. For each, give the repeated addition and multiplication equation and total. Rotate one array to demonstrate that the total is unchanged. Create an incorrect array with one missing item, state the true total, and explain why the rectangular multiplication count would be wrong.","response_prompt":"Complete the array architects: rows, columns and equal groups task independently, showing evidence or working.","quiz":[{"type":"multiple_choice","question":"3 rows of 4?","options":["7","11","12","16"],"correct_index":2,"explanation":"12 follows the original example and reasoning."},{"type":"multiple_choice","question":"Which repeated sum is 3×4?","options":["4+4+4","3+4","3+3+3","4+3+4+3"],"correct_index":0,"explanation":"4+4+4 follows the original example and reasoning."},{"type":"multiple_choice","question":"4 rows of 5?","options":["9","15","20","25"],"correct_index":2,"explanation":"20 follows the original example and reasoning."},{"type":"multiple_choice","question":"5 rows of 4?","options":["10","15","20","25"],"correct_index":2,"explanation":"20 follows the original example and reasoning."},{"type":"multiple_choice","question":"2 rows of 6?","options":["8","10","12","14"],"correct_index":2,"explanation":"12 follows the original example and reasoning."},{"type":"multiple_choice","question":"Does a rotated 3×4 array change total?","options":["No, still 12","Yes, becomes 7","Yes, becomes 24","Only if chairs change colour"],"correct_index":0,"explanation":"No, still 12 follows the original example and reasoning."},{"type":"multiple_choice","question":"3 rows of 5,5,4 have how many?","options":["13","14","15","16"],"correct_index":1,"explanation":"14 follows the original example and reasoning."},{"type":"multiple_choice","question":"Which is an equal-row array?","options":["4,4,4","4,4,3","2,3,4","5,5,4"],"correct_index":0,"explanation":"4,4,4 follows the original example and reasoning."},{"type":"short_answer","question":"Complete the original independent array architects: rows, columns and equal groups challenge.","sample_answer":"5×4=20 plants: 4+4+4+4+4. 3×7=21 packets: 7+7+7. 6×2=12 pots: 2+2+2+2+2+2. The rotated 5×4 array is 4×5, still 20.","marking_guide":"Require complete topic-specific accurate work and supporting reasoning.","explanation":"A strong answer justifies its conclusions."},{"type":"short_answer","question":"Explain a meaningful check, improvement or limitation for array architects: rows, columns and equal groups.","sample_answer":"If four rows have 5,5,5,4 dots, the real total is 19, not 4×5=20, because one item is missing. Equal rows are necessary for that rectangular multiplication model.","marking_guide":"Require complete topic-specific accurate work and supporting reasoning.","explanation":"A strong answer justifies its conclusions."}],"parent_notes":"Parent: Ask for an independent student attempt and a verbal or written explanation before using models.\n\nParent: **Written model answer 1:** 5×4=20 plants: 4+4+4+4+4. 3×7=21 packets: 7+7+7. 6×2=12 pots: 2+2+2+2+2+2. The rotated 5×4 array is 4×5, still 20.\n\nParent: **Written model answer 2:** If four rows have 5,5,5,4 dots, the real total is 19, not 4×5=20, because one item is missing. Equal rows are necessary for that rectangular multiplication model.\n\nParent: Keep authentic evidence and assess the written answers. Formal NESA mapping remains to be checked.","evidence_instructions":"Keep the guided array architects: rows, columns and equal groups practice, independent work, one correction and both written quiz answers.","offline_alternative":"Complete the original information and tasks on paper and retain student work.","extension":"Invent a new array architects: rows, columns and equal groups example and explain its answer.","stage_hints":{"accept":["Review the Array Architects: Rows, Columns and Equal Groups instructions.","Find a particular number or source phrase connected to array architects: rows, columns and equal groups.","Explain the evidence or calculation and check for an error."],"teach0":["Review the See rows and equal groups instructions.","Find a particular number or source phrase connected to see rows and equal groups.","Explain the evidence or calculation and check for an error."],"teach1":["Review the Connect arrays to multiplication instructions.","Find a particular number or source phrase connected to connect arrays to multiplication.","Explain the evidence or calculation and check for an error."],"teach2":["Review the Rotate an array and observe instructions.","Find a particular number or source phrase connected to rotate an array and observe.","Explain the evidence or calculation and check for an error."],"teach3":["Review the Distinguish equal and unequal groups instructions.","Find a particular number or source phrase connected to distinguish equal and unequal groups.","Explain the evidence or calculation and check for an error."],"learn":["Review the Array Architects: Rows, Columns and Equal Groups instructions.","Find a particular number or source phrase connected to array architects: rows, columns and equal groups.","Explain the evidence or calculation and check for an error."],"guided":["Review the Array Architects: Rows, Columns and Equal Groups instructions.","Find a particular number or source phrase connected to array architects: rows, columns and equal groups.","Explain the evidence or calculation and check for an error."],"write":["Review the Array Architects: Rows, Columns and Equal Groups instructions.","Find a particular number or source phrase connected to array architects: rows, columns and equal groups.","Explain the evidence or calculation and check for an error."],"quiz":["Review the Array Architects: Rows, Columns and Equal Groups instructions.","Find a particular number or source phrase connected to array architects: rows, columns and equal groups.","Explain the evidence or calculation and check for an error."],"submit":["Review the Array Architects: Rows, Columns and Equal Groups instructions.","Find a particular number or source phrase connected to array architects: rows, columns and equal groups.","Explain the evidence or calculation and check for an error."]}}') WHERE seed_key='s2-mat-y3-w09-l1';
